var i=[{title:`Die Priorität zuerst`,text:`Die Ermüdung baut sich im Verlauf einer Einheit auf, deshalb kommt die Bewegung, die für dein Ziel am wichtigsten ist, meist dorthin, wo du sie gut ausführen kannst. Schwere Kniebeugen, Drückübungen und harte Zugübungen stehen in Kraftplänen oft am Anfang. Auch neue, komplexe Fertigkeiten gelingen besser mit frischer Konzentration und kontrolliertem Üben. Spare dir die technisch schwerste Übung nicht für einen Abschluss am Ende auf, wenn du am müdesten bist.`},{title:`Verbund- und Isolationsübungen`,text:`Mehrgelenkbewegungen trainieren mehrere Muskeln zusammen und verlangen womöglich mehr Koordination und Ganzkörpereinsatz als Curls oder Seitheben. Eine übliche Reihenfolge ist: Aufwärmen, Hauptübungen, Nebenübungen, Isolationsübungen und optionales Konditionstraining. Das ist eine praktische Gewohnheit, und manche Einheiten und Personen brauchen eine andere Reihenfolge.`},{title:`Was die Belege zeigen`,text:`Neuere ACSM-Belege zeigen, dass Kraftübungen zu Beginn einer Einheit die Kraft in diesen Bewegungen verbessern können. Das Muskelwachstum scheint in vielen Vergleichen weniger von der Übungsreihenfolge abzuhängen. Wenn bessere Klimmzüge dein Hauptziel sind, mache sie vor Übungen, die Arme und Rücken ermüden, auch wenn die Kniebeugen dadurch später kommen.`},{title:`Core und Kondition`,text:`Ein harter Plank oder Carry direkt vor schweren Kniebeugen kann Muskeln ermüden, die du zum Stabilisieren der Kniebeuge brauchst. Leichte Mobilitäts- und Aktivierungsübungen können vorweg kommen, und härteres Core-Training passt womöglich besser nach den Hauptübungen. Wenn Kondition dein Hauptziel ist, kann Cardio der Hauptblock sein, und das Krafttraining wird darum herum angeordnet.`},{title:`Beispiel`,text:`Eine 40-minütige Krafteinheit könnte so aussehen: fünf Minuten Aufwärmen, dann Goblet-Kniebeugen als Hauptübung, Rudern, eine Liegestütz-Variante, ein Hüftbeugen und ein kurzer Satz seitliche Planks. Eine Einheit mit Fertigkeitsschwerpunkt könnte stattdessen vor den anderen Übungen mit einer kontrollierten Klimmzug-Progression mit Körpergewicht beginnen.`}];var t=[{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Frühere ACSM-Prinzipien zur Übungsreihenfolge`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};